files.content:
* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #12122a;
  color: #ffffff;
  font-family: 'Courier New', Courier, monospace;
  text-transform: uppercase;
}

.calculator {
  width: min(90vw, 360px);
  background: #1f1f3d;
  border: 4px solid #ffffff;
  box-shadow: 10px 10px 0 #000000;
  padding: 22px 18px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  text-align: center;
}

h1 {
  margin: 0;
  font-size: 1.6rem;
  letter-spacing: 2px;
  color: #ffd23f;
  text-shadow: 3px 3px 0 #000000;
}

.field {
  display: flex;
  flex-direction: column;
  text-align: left;
  gap: 6px;
}

label {
  font-size: 0.85rem;
  letter-spacing: 1px;
}

input,
select,
button,
output {
  font: inherit;
  color: inherit;
  text-transform: inherit;
  border: 4px solid #ffffff;
  border-radius: 0;
  background: #0f0f2a;
  padding: 12px 10px;
  box-shadow: 4px 4px 0 #000000;
  min-height: 48px;
  width: 100%;
  outline: none;
}

input:focus,
select:focus,
button:focus,
output:focus {
  outline: 4px solid #ffd23f;
  outline-offset: 2px;
}

button {
  background: #ffd23f;
  color: #000000;
  cursor: pointer;
  font-weight: bold;
  letter-spacing: 2px;
}

button:hover {
  background: #ffffff;
}

button:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 #000000;
}

output {
  display: block;
  background: #000000;
  color: #7fff00;
  text-align: right;
  font-size: 1.3rem;
  white-space: nowrap;
  overflow-x: auto;
}

const leftInput = document.getElementById('left');
const rightInput = document.getElementById('right');
const operationSelect = document.getElementById('operation');
const calculateButton = document.getElementById('calculate');
const resultOutput = document.getElementById('result');

function calculate() {
  const a = leftInput.valueAsNumber;
  const b = rightInput.valueAsNumber;

  if (!Number.isFinite(a) || !Number.isFinite(b)) {
    resultOutput.textContent = 'Error';
    return;
  }

  let answer;

  switch (operationSelect.value) {
    case 'add':
      answer = a + b;
      break;
    case 'subtract':
      answer = a - b;
      break;
    case 'multiply':
      answer = a * b;
      break;
    case 'divide':
      if (b === 0) {
        resultOutput.textContent = 'Error';
        return;
      }
      answer = a / b;
      break;
    default:
      resultOutput.textContent = 'Error';
      return;
  }

  if (!Number.isFinite(answer)) {
    resultOutput.textContent = 'Error';
    return;
  }

  resultOutput.textContent = String(answer);
}

calculateButton.addEventListener('click', calculate);

[leftInput, rightInput, operationSelect].forEach((control) => {
  control.addEventListener('keydown', (event) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      calculate();
    }
  });
});
